from pathlib import Path
import base64, html, json

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / '누니드_브랜딩_포트폴리오'
OUT.mkdir(exist_ok=True)
logo = 'data:image/png;base64,' + base64.b64encode((ROOT/'패키지/1차/로고.png').read_bytes()).decode()

def product(kind='bottle', color='#C7DCE7', name='HYDRA SUN BASE', n='01', x=0):
    shapes = {
        'bottle': f'<rect x="78" y="70" width="104" height="44" rx="7" fill="#343831"/><rect x="65" y="106" width="130" height="252" rx="25" fill="url(#body{x})"/><path d="M77 133V321" stroke="white" stroke-opacity=".5" stroke-width="5"/>',
        'tube': f'<path d="M55 90H205L185 330H75Z" fill="url(#body{x})"/><rect x="75" y="329" width="110" height="30" rx="4" fill="#343831"/><path d="M60 98H200" stroke="#fff" stroke-opacity=".5"/>',
        'balm': f'<rect x="92" y="170" width="76" height="185" rx="10" fill="url(#body{x})"/><rect x="92" y="99" width="76" height="100" rx="12" fill="#D68170"/><path d="M103 110V180" stroke="white" stroke-opacity=".4" stroke-width="3"/>',
    }
    return f'''<svg class="product" viewBox="0 0 260 410" role="img" aria-label="{name} 패키지 제안"><defs><linearGradient id="body{x}"><stop stop-color="{color}"/><stop offset=".48" stop-color="#fff" stop-opacity=".92"/><stop offset="1" stop-color="{color}"/></linearGradient></defs><ellipse cx="130" cy="367" rx="86" ry="11" fill="#20211f" opacity=".10"/>{shapes[kind]}<text x="130" y="235" text-anchor="middle" font-family="Georgia" font-size="23" fill="#20211F">nunid</text><text x="130" y="258" text-anchor="middle" font-family="Arial" font-size="7" letter-spacing="1" fill="#20211F">{name}</text><text x="130" y="285" text-anchor="middle" font-family="Arial" font-size="11" fill="#20211F">{n} / DAILY ROUTINE</text></svg>'''

def lineup():
    return '<div class="lineup">'+product(x=1)+product('tube','#E8DFD2','SKIN FIT FLUID','02',2)+product('balm','#E7C4BC','MELTING LIP & CHEEK','03',3)+'</div>'

def cards(items, cls=''):
    return f'<div class="cards {cls}">'+''.join(f'<article><span class="num">0{i+1}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(items))+'</div>'

def flow(items):
    return '<div class="flow">'+'<span class="arrow">→</span>'.join(f'<div>{a}</div>' for a in items)+'</div>'

def screen(mode='home', mobile=False):
    nav='<div class="webnav"><b>nunid</b><span>ROUTINE　 SHOP　 ABOUT</span><span>⌕　 BAG 0</span></div>'
    if mode=='home':
        content='<div class="webhero"><div><small>LESS STEPS, MORE EASE</small><h3>내 피부에 필요한 것만<br>남긴 루틴.</h3><p>스킨케어의 편안함에<br>메이크업의 자연스러움을 더하다.</p><span class="button">나의 루틴 만나기 ↗</span></div>'+lineup()+'</div><div class="webstrip">가볍게 시작하고, 자연스럽게 완성하는 하루</div><div class="minirow"><b>01　SUN & BASE</b><b>02　FACE</b><b>03　CHEEK & LIP</b></div>'
    elif mode=='shop':
        content='<div class="shophead"><small>YOUR DAILY ESSENTIALS</small><h3>필요한 만큼, 가볍게.</h3><p>ALL　 SUN　 FACE　 CHEEK　 LIP　 SET</p></div><div class="shopgrid">'+''.join('<div>'+product(k,c,n,str(i+1),i+10)+f'<b>{n}</b><p>가벼운 밀착 · 자연스러운 표현</p><span class="button">제품 살펴보기 ↗</span></div>' for i,(k,c,n) in enumerate([('bottle','#C7DCE7','HYDRA SUN BASE'),('tube','#E8DFD2','SKIN FIT FLUID'),('balm','#E7C4BC','MELTING BALM')]))+'</div>'
    elif mode=='about':
        content='<div class="aboutscreen"><small>OUR PHILOSOPHY</small><h3>Less steps.<br>More you.</h3><p>스킨케어와 메이크업의 경계를 넘어,<br>내 피부에 필요한 것만 남기는 일.</p><div class="orb"></div></div><div class="minirow">간결한 단계　 /　 편안한 사용감　 /　 자연스러운 표현</div>'
    return f'<div class="browser {"mobileweb" if mobile else ""}"><div class="browserbar"><i></i><i></i><i></i><span>nunid / {mode} · 포트폴리오 재구성 시안</span></div>{nav}{content}</div>'

def phone(kind):
    top='<div class="status">9:41 <span>● ▰</span></div><div class="appnav"><b>nunid</b><span>☰</span></div>'
    if kind==1:
        body='<small>GOOD MORNING, YOUR ROUTINE</small><h3>오늘도,<br>가볍게 시작해요.</h3><div class="appvisual">'+product(x=51)+'</div><div class="appcard"><b>나의 모닝 루틴</b><p>SUN → FACE → COLOR</p><span class="button">루틴 확인하기 ↗</span></div>'
    elif kind==2:
        body='<small>MY ROUTINE</small><h3>필요한 세 단계.</h3>'+''.join(f'<div class="routineitem"><span>0{i+1}</span><div><b>{a}</b><p>{b}</p></div><em>✓</em></div>' for i,(a,b) in enumerate([('SUN & BASE','피부 바탕을 가볍게 정돈'),('FACE','본연의 결을 살리는 표현'),('CHEEK & LIP','필요한 만큼의 생기')]))+'<div class="appcard"><p>이 루틴을 저장하고<br>다음에도 간편하게 만나세요.</p><span class="button">나의 루틴 저장</span></div>'
    else:
        body='<small>YOUR ESSENTIAL</small><h3>Skin fit fluid</h3><div class="appvisual">'+product('tube','#E8DFD2','SKIN FIT FLUID','02',53)+'</div><div class="appcard"><b>얇고 편안한 피부 표현</b><p>내 루틴에 저장된 제품을 다시 만나요.</p><span class="button">다시 구매하기 ↗</span></div>'
    return '<div class="phone">'+top+'<div class="appbody">'+body+'</div><div class="apptabs">홈　　 루틴　　 쇼핑　　 마이</div></div>'

