add('10 / PACKAGE SYSTEM','사용 순서가<br>제품의 언어가 되도록.','제품의 역할과 단계가 한눈에 연결되는 패키지 시스템을 제안합니다.', '<div class="packagegrid"><div>'+lineup()+'</div><div>'+cards([('01 / SUN & BASE','미스트 블루 · 피부 바탕을 정돈하는 시작'),('02 / FACE','뉴트럴 페이퍼 · 자연스러운 피부 표현'),('03 / CHEEK & LIP','소프트 코랄 · 필요한 만큼 더하는 생기')],'stack')+'</div></div><p class="note">브리프의 3-Step 루틴을 바탕으로 새로 구성한 패키지 그래픽 콘셉트입니다.</p>',source='대표 루틴·제품 분류 기반 / 용기·라벨은 신규 제작 제안',state='신규 패키지 콘셉트 제안')
add('11 / PACKAGE APPLICATION','세 제품이 만나,<br>하나의 루틴이 되다.','단품부터 세트까지 동일한 정보 위계를 유지합니다.', '<div class="packscene"><div class="packbox"><span>nunid</span><small>THE DAILY ROUTINE<br>01 — 02 — 03</small><b>LESS STEPS, MORE EASE</b></div><div class="packproducts">'+lineup()+'</div><div class="packcaption"><small>ROUTINE SET / CONCEPT</small><h3>열고, 이해하고,<br>순서대로 사용하기.</h3><p>브랜드 → 제품 역할 → 단계 순서로<br>읽히는 세트 패키지를 제안합니다.</p></div></div>','sand',source='신규 패키지 제안 / 실물 제작·소재 검증 전',state='신규 패키지 적용 시안')
add('12 / DIGITAL STRATEGY & IA','제품보다 먼저,<br>루틴을 이해하는 구조.','기존 사이트맵을 브랜드 이해와 두 가지 탐색 경로 중심으로 축약했습니다.', '<div class="iaroot">NUNID HOME</div><div class="iatree">'+''.join(f'<article><b>{a}</b>'+''.join(f'<span>{b}</span>' for b in bs)+'</article>' for a,bs in [('ROUTINE',['3-Step 가이드','단계별 역할','세트 탐색']),('SHOP',['SUN / FACE','CHEEK / LIP','SET']),('TEXTURE & PROOF',['제형과 피부 표현','3대 제품 원칙','핵심 기능']),('ABOUT',['브랜드 철학','간결한 루틴의 배경','브랜드 메시지'])])+'</div><div class="utility">공통 기능　 검색 / Quick Spec / 장바구니 → 주문 연결</div><p class="note">포트폴리오 설명용 축약 IA · 상세 결제와 회원가입은 메인 설계 범위에서 분리</p>',source='김유진 사이트맵.md · 원본 브리프의 범위')
add('13 / USER FLOW','내가 원하는 방식으로<br>루틴에 도착하기.','완성된 루틴이 필요한 사람과 단품을 비교하는 사람을 함께 고려합니다.', '<div class="flowlabel">PATH A / 루틴 중심 탐색</div>'+flow(['메인 진입','루틴 시작하기','3-Step 역할 확인','세트 선택','장바구니'])+'<div class="flowlabel">PATH B / 단품 중심 탐색</div>'+flow(['메인 진입','제품 둘러보기','카테고리 선택','Quick Spec','장바구니'])+'<div class="flowinsight"><b>설계 원칙</b><p>같은 제품군을 서로 다른 탐색 목적에 맞게 연결합니다.<br>선택 직전에는 기능·제형·가격·사용 순서를 확인할 수 있도록 합니다.</p></div>',source='김유진 서비스_흐름도.md · 분석 보고서 기반')
add('14 / WEB WIREFRAME','메시지에서 선택까지,<br>정보의 순서를 설계하다.','한 화면에서 하나의 핵심 질문에 답하는 구조입니다.', '<div class="wireweb"><div><div class="wfblock">HEADER / 브랜드 · 루틴 · 제품 · 제형</div><div class="wfblock hero">HERO<br><b>핵심 가치 + 루틴 / 제품 CTA</b></div><div class="wfblock">PROBLEM → SOLUTION</div><div class="wfblock">SIGNATURE 3-STEP ROUTINE</div><div class="wfblock">TEXTURE / PRODUCTS / TRUST</div></div><div class="wireannotations"><p><b>01 / 이해</b> 첫 화면에서 어떤 브랜드인지 파악</p><p><b>02 / 공감</b> 복잡한 루틴과 선택의 부담 연결</p><p><b>03 / 판단</b> 사용 순서와 제품의 역할 제공</p><p><b>04 / 선택</b> 루틴 세트와 단품 탐색으로 연결</p></div></div>',source='기존 스토리보드 1~4차 · 화면 설계서의 핵심 구조 재편집')
add('15 / WEB DESIGN','첫 화면에서 만나는<br>누니드다운 가벼움.','브랜드 메시지와 대표 루틴을 하나의 시선 흐름으로 연결했습니다.',screen(),source='기존 메인페이지 카피·구조 기반 / 신규 포트폴리오 화면 디자인',state='웹 화면 재구성 시안')
add('16 / WEB EXPERIENCE','비교는 명확하게,<br>브랜드는 일관되게.','제품 탐색과 브랜드 소개에도 같은 시각 원칙을 이어갑니다.', '<div class="twoscreens">'+screen('shop')+screen('about')+'</div><div class="twoexplain"><p><b>SHOP</b> 카테고리 → 제형·기능 → 제품 확인</p><p><b>ABOUT</b> 철학 → 사용 경험 → 제품 탐색</p></div>',source='카테고리페이지.html · 브랜드소개페이지.html 구조 기반',state='웹 서브 화면 재구성 시안')
add('17 / ITERATION','더 빠른 판단을 위해,<br>네 가지 접점을 정리하다.','사후관리 문서에 기록된 개선 방향을 전후 구조로 보여줍니다.', '<div class="iteration"><div><small>BEFORE / 문제 구조</small><article><span>01</span> 안심 정보가 하단에 집중</article><article><span>02</span> 모바일에 전체 15개 제품 나열</article><article><span>03</span> 스펙과 담기가 같은 강조</article><article><span>04</span> 담기 후 다음 행동 안내 부족</article></div><div><small>AFTER / 개선 방향</small><article><span>↗</span> 상단과 세트 주변에 정보 제공</article><article><span>↗</span> 세트 우선 · 전체는 단계적 노출</article><article><span>↗</span> 담기를 주 행동으로 강조</article><article><span>↗</span> 첫 담기 드로어 · 다음 행동 링크</article></div></div><p class="note">문서 기반 설계 개선 사례입니다. 전환율·이탈률·접근성 점수를 실측 성과로 제시하지 않습니다.</p>',source='사후관리 02_오류_수정_요구서.md ~ 04_수정완료_및_재검증보고서.md')
add('18 / MOBILE WEB','작은 화면에서도<br>같은 순서로 이해하도록.','핵심 메시지와 행동을 우선하고, 제품 정보는 단계적으로 보여줍니다.', '<div class="mobilelayout"><div class="mobileframe">'+screen('home',True)+'</div><div>'+cards([('메시지의 우선순위 유지','브랜드 가치 → 대표 루틴 → 제품 정보 순서로 정리합니다.'),('탐색 길이 조절','세트 우선과 제품 펼치기로 한 번에 보이는 정보를 줄입니다.'),('행동의 위계 유지','루틴 보기와 제품 탐색을 구분하고 다음 행동을 분명하게 표시합니다.')],'stack')+'</div></div>',source='기존 반응형 명세 및 사후관리 문서 기반',state='모바일 웹 재구성 시안')
add('19 / APP EXTENSION','첫 구매 다음에도,<br>나의 루틴이 이어지도록.','웹의 브랜드 탐색 경험에서 저장과 재방문 경험으로 확장하는 앱 제안입니다.', '<div class="appextension"><div><small>WEB → APP</small><h3>발견에서,<br>반복되는 일상으로.</h3><p class="lead">웹은 브랜드와 제품을 이해하는 곳.<br>앱은 나의 루틴을 저장하고 다시 만나는 곳.</p>'+flow(['루틴 탐색','나의 루틴 저장','저장 제품 확인','재구매 연결'])+'<p class="note">실제 고객 수요 검증 전의 확장 가설입니다.<br>개인화 진단·피부 효능 판단 기능은 포함하지 않았습니다.</p></div>'+phone(2)+'</div>',source='기존 앱 자료 없음 / 새로 제안한 서비스 방향',state='신규 앱 확장 기획')
add('20 / APP DESIGN','매일 다시 만나는<br>나만의 에센셜.','홈 · 나의 루틴 · 저장 제품의 세 화면으로 핵심 경험을 제안합니다.', '<div class="phones">'+phone(1)+phone(2)+phone(3)+'</div><div class="phonelabels"><span>01 / HOME</span><span>02 / MY ROUTINE</span><span>03 / SAVED PRODUCT</span></div>',source='신규 앱 UI 콘셉트 / 실제 저장·결제 기능 미구현',state='신규 앱 디자인 제안')
add('21 / REFLECTION','필요한 것만 남기는 일은,<br>경험 전체를 설계하는 일.','브랜드의 한 문장이 제품과 디지털 접점에서 같은 방식으로 읽히도록 정리했습니다.',cards([('브랜드에서 경험으로','간결함·편안함·자연스러움을 루틴, 패키지 단계, 정보 위계에 연결했습니다.'),('결과보다 선택의 이유','왜 이 순서와 구조를 제안했는지 기획 근거와 산출물을 함께 보여줍니다.'),('다음 검증 과제','제품 분류 이해도, 루틴 선택 과제, 모바일 탐색과 앱 저장 수요를 확인해야 합니다.')])+'<div class="closing">Less steps. <em>More you.</em><span>nunid / BRAND EXPERIENCE CONCEPT</span></div><p class="note">제출 전 확정: 본인 역할·기여율·기간 / 최종 로고 / 신규 패키지·앱 제안의 채택 여부</p>','blue',source='프로젝트 자료 종합 및 후속 검증 제안')

